import { useEffect, useState } from "react";
import { Navbar, Container, Nav } from "react-bootstrap";
import logo from '../assets/img/logo.svg';
import navIcon1 from '../assets/img/nav-icon1.svg';
import navIcon2 from '../assets/img/nav-icon2.svg';
import navIcon3 from '../assets/img/nav-icon3.svg';
export const NavBar = () => {
    const[activeLink, setActiveLink] = useState('home');
    const [scrolled, seScrolled] = useState (false);
    
    useEffect(() => {
        const onScroll = () => {
            if (window.scrollY > 50){
                seScrolled(true);

            }else{
                seScrolled(false);
            }
        }

        window.addEventListener("scroll", onScroll);

        return () => window.removeEventListener("scroll", onScroll);
    }, [])

    const onUpdateActivateLink = (value) => {
        setActiveLink(value);
    }
    
    return (
    <Navbar expand="lg" className={scrolled ? "scrolled": ""}>
      <Container>
       <Navbar.Brand href="#home">
          <span className="logo-text">Portafolio Web</span>
      </Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav"> 
            <span className="navbar-togger-icon"></span>
        </Navbar.Toggle>
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="me-auto">
            <Nav.Link href="#home" className={activeLink === 'home'? 'active navbar-link' : 'navbar-link'} onClick={() => onUpdateActivateLink('home')}>Presentación</Nav.Link>
            <Nav.Link href="#skills" className={activeLink === 'skills'? 'active navbar-link' : 'navbar-link'} onClick={() => onUpdateActivateLink('skills')} >Habilidades</Nav.Link>
            <Nav.Link href="#projects"className={activeLink === 'projects'? 'active navbar-link' : 'navbar-link'} onClick={() => onUpdateActivateLink('projects')}>Proyectos</Nav.Link>
            
          </Nav>

          <span className="navbar-text">
            <div className="social-icon">
                <a href="https://www.linkedin.com/in/marina-desiderio-vergara-b97a613b2/"><img src={navIcon1} alt=""/></a>
                
            </div>

            <button 
                className="vvd" 
                onClick={() => window.open('https://www.canva.com/design/DAHEPOWtmic/GaLubeNbknXCv_69x3ZxIQ/edit?utm_content=DAHEPOWtmic&utm_campaign=designshare&utm_medium=link2&utm_source=sharebutton', '_blank')}>
                <span>Currículum</span>
            </button>
            
          </span>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  )
}

